  ],
  "nct_id": "NCT07441525",
  "phase": "EARLY_PHASE1",
  "source": "ClinicalTrials.gov",
  "sponsor": "Union Hospital, Tongji Medical College, Huazhong University of Science and Technology",
  "start_date": "2026-02-03",
  "status": "RECRUITING",
  "study_type": "INTERVENTIONAL",
  "summary": "This is a single-arm, open-label, investigator-initiated trial (IIT) designed to evaluate the safety, tolerability, pharmacokinetics (PK), pharmacodynamics (PD), and efficacy of RD06-05 in subjects with autoantibody-mediated autoimmune hematological diseases. The enrolled population consists of patients with active autoimmune hematological diseases, including primary immune thrombocytopenic purpura (ITP), autoimmune hemolytic anemia (AIHA), and Evans syndrome.\n\nThis study sets two dose groups: 6 × 10⁶ CAR⁺T cells/kg and 10 × 10⁶ CAR⁺T cells/kg, with the initial dose being 6 × 10⁶ CAR⁺T cells/kg. To reduce efficacy risks, the dose may be escalated to 10 × 10⁶ CAR⁺T cells/kg following evaluation and recommendation by the Safety Review Committee (SRC). The SRC's recommendation on dose escalation will be based on a comprehensive assessment of all available safety, pharmacokinetic (PK), pharmacodynamic (PD), and preliminary efficacy data.",
  "title": "UCAR-T Targeting CD19/BCMA in Subjects With Autoantibody-Mediated Autoimmune Benign Hematological Diseases"
}

